1	// === collision.js — Racing Game ===
2	// Car-to-car and car-to-track collision detection and response.
3	// Uses AABB broad phase + SAT narrow phase for rotated-rect car bodies.
4	// Off-track detection with graduated friction penalties.
5	
6	// ─── Constants (extend R.CONFIG) ───────────────────────────────────────────
7	
8	R.CONFIG.CAR_WIDTH            = R.CONFIG.CAR_WIDTH            || 40;
9	R.CONFIG.CAR_HEIGHT           = R.CONFIG.CAR_HEIGHT           || 70;
10	R.CONFIG.COLLISION_DAMPING    = R.CONFIG.COLLISION_DAMPING    || 0.7;
11	R.CONFIG.COLLISION_SPEED_LOSS = R.CONFIG.COLLISION_SPEED_LOSS || 0.85;
12	R.CONFIG.OFFROAD_FRICTION     = R.CONFIG.OFFROAD_FRICTION     || 0.92;
13	R.CONFIG.OFFROAD_DEEP_PENALTY = R.CONFIG.OFFROAD_DEEP_PENALTY || 0.80;
14	R.CONFIG.OFFROAD_DEEP_THRESH  = R.CONFIG.OFFROAD_DEEP_THRESH  || 50;
15	R.CONFIG.MIN_SPEED            = R.CONFIG.MIN_SPEED            || 0.5;
16	R.CONFIG.MIN_COLLISION_SPEED  = R.CONFIG.MIN_COLLISION_SPEED  || 2.0;
17	R.CONFIG.SPARK_SPEED_THRESH   = R.CONFIG.SPARK_SPEED_THRESH   || 4.0;
18	R.CONFIG.MAX_SIMULTANEOUS     = R.CONFIG.MAX_SIMULTANEOUS     || 8;
19	
20	// ─── Helpers ───────────────────────────────────────────────────────────────
21	
22	/**
23	 * Rotate a point (px, py) around origin (ox, oy) by angle (radians).
24	 */
25	R._rotatePoint = function(px, py, ox, oy, angle) {
26	  const cos = Math.cos(angle);
27	  const sin = Math.sin(angle);
28	  const dx = px - ox;
29	  const dy = py - oy;
30	  return {
31	    x: ox + dx * cos - dy * sin,
32	    y: oy + dx * sin + dy * cos
33	  };
34	};
35	
36	/**
37	 * Project polygon points onto an axis. Returns { min, max }.
38	 */
39	R._projectPolygon = function(points, axisX, axisY) {
40	  let min = Infinity;
41	  let max = -Infinity;
42	  for (let i = 0; i < points.length; i++) {
43	    const dot = points[i].x * axisX + points[i].y * axisY;
44	    if (dot < min) min = dot;
45	    if (dot > max) max = dot;
46	  }
47	  return { min, max };
48	};
49	
50	/**
51	 * Get the 4 corner points of a car as a rotated rectangle.
52	 * Car origin (x, y) is the center of the rectangle.
53	 */
54	R._getCarCorners = function(car) {
55	  const hw = R.CONFIG.CAR_WIDTH * 0.5;
56	  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
57	  const cx = car.x;
58	  const cy = car.y;
59	  const angle = car.angle || 0;
60	
61	  const local = [
62	    { x: -hw, y: -hh },
63	    { x:  hw, y: -hh },
64	    { x:  hw, y:  hh },
65	    { x: -hw, y:  hh }
66	  ];
67	
68	  const corners = [];
69	  for (let i = 0; i < 4; i++) {
70	    corners.push(R._rotatePoint(
71	      cx + local[i].x, cy + local[i].y, cx, cy, angle
72	    ));
73	  }
74	  return corners;
75	};
76	
77	/**
78	 * Get edge normals of a polygon for SAT (perpendicular to each edge, normalized).
79	 */
80	R._getNormals = function(corners) {
81	  const normals = [];
82	  for (let i = 0; i < corners.length; i++) {
83	    const j = (i + 1) % corners.length;
84	    const edgeX = corners[j].x - corners[i].x;
85	    const edgeY = corners[j].y - corners[i].y;
86	    const len = Math.sqrt(edgeX * edgeX + edgeY * edgeY);
87	    if (len < 0.0001) continue;
88	    normals.push({ x: -edgeY / len, y: edgeX / len });
89	  }
90	  return normals;
91	};
92	
93	/**
94	 * Overlap amount on an axis between two projections.
95	 * Positive = overlapping, negative/zero = separated.
96	 */
97	R._overlapOnAxis = function(projA, projB) {
98	  return Math.min(projA.max, projB.max) - Math.max(projA.min, projB.min);
99	};
100	
101	// ─── AABB ───────────────────────────────────────────────────────────────────
102	
103	/**
104	 * Axis-aligned bounding box for a car. Uses max extent of the rotated rectangle
105	 * (a conservative circle-bounds approximation).
106	 *
107	 * @param {Object} car — { x, y, angle }
108	 * @returns {{ minX: number, maxX: number, minY: number, maxY: number }}
109	 */
110	R.carAABB = function(car) {
111	  const hw = R.CONFIG.CAR_WIDTH * 0.5;
112	  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
113	  const angle = car.angle || 0;
114	  const absCos = Math.abs(Math.cos(angle));
115	  const absSin = Math.abs(Math.sin(angle));
116	  const radiusX = hw * absCos + hh * absSin;
117	  const radiusY = hw * absSin + hh * absCos;
118	
119	  return {
120	    minX: car.x - radiusX,
121	    maxX: car.x + radiusX,
122	    minY: car.y - radiusY,
123	    maxY: car.y + radiusY
124	  };
125	};
126	
127	/**
128	 * Test if two AABBs overlap.
129	 */
130	R._aabbOverlap = function(a, b) {
131	  return a.minX < b.maxX && a.maxX > b.minX && a.minY < b.maxY && a.maxY > b.minY;
132	};
133	
134	// ─── Car-to-Car Collision (SAT) ─────────────────────────────────────────────
135	
136	/**
137	 * Detailed collision detection between two cars using Separating Axis Theorem.
138	 * Each car is a 40x70 rotated rectangle.
139	 *
140	 * @param {Object} carA
141	 * @param {Object} carB
142	 * @returns {{ hit: boolean, overlapX: number, overlapY: number, depth: number } | null}
143	 */
144	R.checkCarToCar = function(carA, carB) {
145	  // Broad phase: AABB
146	  if (!R._aabbOverlap(R.carAABB(carA), R.carAABB(carB))) {
147	    return null;
148	  }
149	
150	  // Narrow phase: SAT
151	  const cornersA = R._getCarCorners(carA);
152	  const cornersB = R._getCarCorners(carB);
153	  const axes = R._getNormals(cornersA).concat(R._getNormals(cornersB));
154	
155	  let minOverlap = Infinity;
156	  let minAxisX = 0;
157	  let minAxisY = 0;
158	
159	  for (let i = 0; i < axes.length; i++) {
160	    const ax = axes[i].x;
161	    const ay = axes[i].y;
162	    const projA = R._projectPolygon(cornersA, ax, ay);
163	    const projB = R._projectPolygon(cornersB, ax, ay);
164	    const overlap = R._overlapOnAxis(projA, projB);
165	
166	    if (overlap <= 0) return null; // separating axis found
167	
168	    if (overlap < minOverlap) {
169	      minOverlap = overlap;
170	      minAxisX = ax;
171	      minAxisY = ay;
172	    }
173	  }
174	
175	  return {
176	    hit: true,
177	    overlapX: minAxisX * minOverlap,
178	    overlapY: minAxisY * minOverlap,
179	    depth: minOverlap
180	  };
181	};
182	
183	// ─── Collision Resolution ───────────────────────────────────────────────────
184	
185	/**
186	 * Resolve a collision between two cars: push apart and adjust velocities.
187	 *
188	 * Push ratios:
189	 *   - Both moving: 50% each
190	 *   - One stationary (speed < MIN_SPEED): stationary car gets 70% push,
191	 *     moving car takes 30%
192	 *
193	 * Velocity impulse:
194	 *   - Relative velocity along collision normal
195	 *   - Equal-mass damped exchange
196	 *   - COLLISION_DAMPING applied to both cars' speed
197	 *
198	 * @param {Object} carA
199	 * @param {Object} carB
200	 * @param {{ overlapX: number, overlapY: number, depth: number }} overlap
201	 */
202	R.resolveCollision = function(carA, carB, overlap) {
203	  const depth = overlap.depth;
204	  if (depth <= 0) return;
205	
206	  const speedA = Math.abs(carA.speed || 0);
207	  const speedB = Math.abs(carB.speed || 0);
208	  const aStationary = speedA < R.CONFIG.MIN_SPEED;
209	  const bStationary = speedB < R.CONFIG.MIN_SPEED;
210	
211	  // Determine push ratios
212	  let pushRatioA, pushRatioB;
213	  if (aStationary && !bStationary) {
214	    pushRatioA = 0.7; pushRatioB = 0.3;
215	  } else if (bStationary && !aStationary) {
216	    pushRatioA = 0.3; pushRatioB = 0.7;
217	  } else {
218	    pushRatioA = 0.5; pushRatioB = 0.5;
219	  }
220	
221	  // Push apart
222	  carA.x -= overlap.overlapX * pushRatioA;
223	  carA.y -= overlap.overlapY * pushRatioA;
224	  carB.x += overlap.overlapX * pushRatioB;
225	  carB.y += overlap.overlapY * pushRatioB;
226	
227	  // Velocity exchange
228	  const nx = overlap.overlapX / (depth || 0.001);
229	  const ny = overlap.overlapY / (depth || 0.001);
230	
231	  const vAx = Math.cos(carA.angle || 0) * (carA.speed || 0);
232	  const vAy = Math.sin(carA.angle || 0) * (carA.speed || 0);
233	  const vBx = Math.cos(carB.angle || 0) * (carB.speed || 0);
234	  const vBy = Math.sin(carB.angle || 0) * (carB.speed || 0);
235	
236	  const relVelN = (vAx - vBx) * nx + (vAy - vBy) * ny;
237	
238	  // Only resolve if cars are approaching
239	  if (relVelN > 0) {
240	    if (!aStationary && !bStationary) {
241	      // Equal-mass damped exchange: each car moves toward average speed
242	      const avgSpeed = (carA.speed + carB.speed) / 2;
243	      carA.speed = avgSpeed - (carA.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
244	      carB.speed = avgSpeed - (carB.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
245	    } else if (aStationary) {
246	      carB.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
247	      carA.speed = carB.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
248	    } else {
249	      carA.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
250	      carB.speed = carA.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
251	    }
252	
253	    // Both lose energy
254	    carA.speed *= R.CONFIG.COLLISION_DAMPING;
255	    carB.speed *= R.CONFIG.COLLISION_DAMPING;
256	  }
257	
258	  // Clamp tiny speeds to zero
259	  if (Math.abs(carA.speed) < R.CONFIG.MIN_SPEED * 0.5) carA.speed = 0;
260	  if (Math.abs(carB.speed) < R.CONFIG.MIN_SPEED * 0.5) carB.speed = 0;
261	};
262	
263	// ─── Boundary Checking ──────────────────────────────────────────────────────
264	
265	/**
266	 * Check if a car is off the track and apply penalties.
267	 *
268	 * - Uses R.isOnTrack(car.x, car.z) to determine track position
269	 * - Off track: applies OFFROAD_FRICTION (shallow) or OFFROAD_DEEP_PENALTY (deep)
270	 * - Deep off track (>50px from edge) + speed > 3: aggressive speed reduction
271	 * - Spawns dust particles via R.spawnDust()
272	 * - Sets car._offRoadSteerScale = 0.6 for reduced steering control
273	 *
274	 * @param {Object} car
275	 * @param {number} dt — delta time (seconds), unused but accepted for API compatibility
276	 */
277	R.checkCarToBoundary = function(car, dt) {
278	  if (typeof R.isOnTrack !== 'function') return;
279	
280	  const carZ = (car.z !== undefined) ? car.z : 0;
281	  if (R.isOnTrack(car.x, carZ)) {
282	    car._offTrack = false;
283	    car._offTrackDepth = 0;
284	    car._offRoadSteerScale = 1;
285	    return;
286	  }
287	
288	  // Off track — determine depth
289	  car._offTrack = true;
290	  const testOffset = R.CONFIG.OFFROAD_DEEP_THRESH;
291	  let deepOff;
292	
293	  if (typeof R.isOnTrack === 'function') {
294	    const probeX = car.x + (car.x > 0 ? -testOffset : testOffset);
295	    deepOff = !R.isOnTrack(probeX, carZ);
296	  } else {
297	    deepOff = false;
298	  }
299	
300	  car._offTrackDepth = deepOff ? R.CONFIG.OFFROAD_DEEP_THRESH + 1 : 30;
301	
302	  // Apply friction
303	  const friction = deepOff ? R.CONFIG.OFFROAD_DEEP_PENALTY : R.CONFIG.OFFROAD_FRICTION;
304	  car.speed *= friction;
305	
306	  // Aggressive scrubbing for fast cars deep off track
307	  if (deepOff && Math.abs(car.speed) > 3) {
308	    car.speed *= R.CONFIG.OFFROAD_DEEP_PENALTY;
309	  }
310	
311	  if (Math.abs(car.speed) < R.CONFIG.MIN_SPEED * 0.3) {
312	    car.speed = 0;
313	  }
314	
315	  // Dust particles
316	  if (typeof R.spawnDust === 'function' && Math.abs(car.speed) > 0.5) {
317	    R.spawnDust(car.x, car.y, deepOff ? 4 : 2);
318	  }
319	
320	  // Reduced steering off-road
321	  car._offRoadSteerScale = 0.6;
322	};
323	
324	// ─── Per-Frame Collision Check ──────────────────────────────────────────────
325	
326	/**
327	 * Main entry point. Called each frame during 'racing' phase.
328	 *
329	 * Pipeline:
330	 *   1. Gather active cars (player + AI)
331	 *   2. AABB broad phase → candidate pairs
332	 *   3. SAT narrow phase → confirmed collisions
333	 *   4. Sort by overlap depth (deepest first)
334	 *   5. Resolve each collision (push apart + impulse + effects)
335	 *   6. Re-check boundaries for all cars (collisions may push cars off track)
336	 *
337	 * Edge cases handled:
338	 *   - Multiple simultaneous collisions: resolved in depth order, max per car = 3
339	 *   - Very slow collisions: no sparks/sound, just positional nudging
340	 *   - One car stationary: push ratio biased toward stationary car
341	 *   - Car pushed off track: boundary re-check after resolution
342	 */
343	
344	// Debug/metrics (populated each frame)
345	R._lastCollisionInfo = null;
346	R._collisionCountThisFrame = 0;
347	
348	R.checkCollisions = function() {
349	  R._collisionCountThisFrame = 0;
350	  R._lastCollisionInfo = null;
351	
352	  if (R.state.phase !== 'racing') return;
353	
354	  // 1. Gather cars
355	  const cars = [];
356	  if (R.playerCar) cars.push(R.playerCar);
357	  if (R.aiCars && R.aiCars.length > 0) {
358	    for (let i = 0; i < R.aiCars.length; i++) cars.push(R.aiCars[i]);
359	  }
360	
361	  if (cars.length < 2) {
362	    for (let i = 0; i < cars.length; i++) R.checkCarToBoundary(cars[i], 0.016);
363	    return;
364	  }
365	
366	  // 2. AABB broad phase
367	  const aabbs = [];
368	  for (let i = 0; i < cars.length; i++) aabbs.push(R.carAABB(cars[i]));
369	
370	  const candidates = [];
371	  for (let i = 0; i < cars.length; i++) {
372	    for (let j = i + 1; j < cars.length; j++) {
373	      if (R._aabbOverlap(aabbs[i], aabbs[j])) {
374	        candidates.push({ a: cars[i], b: cars[j] });
375	      }
376	    }
377	  }
378	
379	  if (candidates.length === 0) {
380	    for (let i = 0; i < cars.length; i++) R.checkCarToBoundary(cars[i], 0.016);
381	    return;
382	  }
383	
384	  // 3. SAT narrow phase
385	  const collisions = [];
386	  for (let k = 0; k < candidates.length; k++) {
387	    const { a, b } = candidates[k];
388	    const result = R.checkCarToCar(a, b);
389	    if (result && result.hit) {
390	      collisions.push({ carA: a, carB: b, overlap: result, depth: result.depth });
391	    }
392	  }
393	
394	  R._collisionCountThisFrame = collisions.length;
395	  if (collisions.length === 0) {
396	    for (let i = 0; i < cars.length; i++) R.checkCarToBoundary(cars[i], 0.016);
397	    return;
398	  }
399	
400	  // 4. Sort deepest first
401	  collisions.sort(function(c1, c2) { return c2.depth - c1.depth; });
402	
403	  // 5. Resolve collisions
404	  const maxResolve = Math.min(collisions.length, R.CONFIG.MAX_SIMULTANEOUS);
405	  const resolvedCars = {};
406	  const involvedCarKeys = [];
407	
408	  for (let k = 0; k < maxResolve; k++) {
409	    const col = collisions[k];
410	
411	    const keyA = col.carA._id || 'player';
412	    const keyB = col.carB._id || 'ai_' + R.aiCars.indexOf(col.carB);
413	
414	    resolvedCars[keyA] = (resolvedCars[keyA] || 0) + 1;
415	    resolvedCars[keyB] = (resolvedCars[keyB] || 0) + 1;
416	
417	    // Limit per-car resolutions to prevent jitter
418	    if (resolvedCars[keyA] > 3 || resolvedCars[keyB] > 3) continue;
419	
420	    const speedA = Math.abs(col.carA.speed || 0);
421	    const speedB = Math.abs(col.carB.speed || 0);
422	    const avgSpeed = (speedA + speedB) / 2;
423	
424	    // Resolve
425	    R.resolveCollision(col.carA, col.carB, col.overlap);
426	
427	    // Effects
428	    const midpointX = (col.carA.x + col.carB.x) / 2;
429	    const midpointY = (col.carA.y + col.carB.y) / 2;
430	
431	    if (avgSpeed > R.CONFIG.SPARK_SPEED_THRESH) {
432	      const intensity = Math.min(avgSpeed / 20, 1);
433	      if (typeof R.spawnSparks === 'function') R.spawnSparks(midpointX, midpointY, intensity);
434	      if (typeof R.playSound === 'function') R.playSound('crash', intensity);
435	    } else if (avgSpeed > R.CONFIG.MIN_COLLISION_SPEED) {
436	      const intensity = avgSpeed / R.CONFIG.SPARK_SPEED_THRESH * 0.5;
437	      if (typeof R.spawnSparks === 'function') R.spawnSparks(midpointX, midpointY, intensity);
438	      if (typeof R.playSound === 'function') R.playSound('crash', intensity * 0.3);
439	    }
440	    // Below MIN_COLLISION_SPEED: no effects, just nudging
441	
442	    R._lastCollisionInfo = { carA: keyA, carB: keyB, depth: col.depth, avgSpeed: avgSpeed };
443	
444	    if (involvedCarKeys.indexOf(keyA) === -1) involvedCarKeys.push(keyA);
445	    if (involvedCarKeys.indexOf(keyB) === -1) involvedCarKeys.push(keyB);
446	  }
447	
448	  // 6. Boundary re-check for all cars (collisions may have pushed cars off track)
449	  const boundaryChecked = {};
450	
451	  // Check involved cars first
452	  for (let k = 0; k < maxResolve; k++) {
453	    const col = collisions[k];
454	    const keyA = col.carA._id || 'player';
455	    const keyB = col.carB._id || 'ai_' + R.aiCars.indexOf(col.carB);
456	
457	    if (!boundaryChecked[keyA]) {
458	      R.checkCarToBoundary(col.carA, 0.016);
459	      boundaryChecked[keyA] = true;
460	    }
461	    if (!boundaryChecked[keyB]) {
462	      R.checkCarToBoundary(col.carB, 0.016);
463	      boundaryChecked[keyB] = true;
464	    }
465	  }
466	
467	  // Then check remaining cars
468	  for (let i = 0; i < cars.length; i++) {
469	    const carKey = cars[i]._id || (cars[i] === R.playerCar ? 'player' : 'ai_' + R.aiCars.indexOf(cars[i]));
470	    if (!boundaryChecked[carKey]) {
471	      R.checkCarToBoundary(cars[i], 0.016);
472	      boundaryChecked[carKey] = true;
473	    }
474	  }
475	};
476	
477	// ─── Exports ────────────────────────────────────────────────────────────────
478	// Public API (attached to window.R):
479	//   R.checkCollisions()                        — per-frame entry point
480	//   R.checkCarToCar(carA, carB)                — SAT collision test
481	//   R.checkCarToBoundary(car, dt)              — off-track penalty check
482	//   R.resolveCollision(carA, carB, overlap)    — push apart + impulse
483	//   R.carAABB(car)                             — AABB bounding box
484	//
485	// Internal helpers (on R for testability):
486	//   R._rotatePoint(px, py, ox, oy, angle)
487	//   R._projectPolygon(points, axisX, axisY)
488	//   R._getCarCorners(car)
489	//   R._getNormals(corners)
490	//   R._overlapOnAxis(projA, projB)
491	//   R._aabbOverlap(a, b)
492	//
493	// Debug/metrics:
494	//   R._lastCollisionInfo       — last resolved collision { carA, carB, depth, avgSpeed }
495	//   R._collisionCountThisFrame — number of active collisions this frame
496

