460	/* ==========================================================================
461	   R.worldToScreen(wx, wy, wz) — World-to-screen projection
462	   ========================================================================== */
463	
464	/**
465	 * Converts world coordinates to screen coordinates using perspective projection.
466	 * wz controls depth-based scaling: larger wz = farther away = smaller on screen.
467	 *
468	 * The camera position (R.camera.x, R.camera.y) defines the screen centre.
469	 * If R.camera.worldZ is set, wz is treated as relative to the camera's Z
470	 * (for proper perspective during racing). Otherwise wz is used as-is.
471	 *
472	 * @param {number} wx World X coordinate
473	 * @param {number} wy World Y coordinate (elevation)
474	 * @param {number} wz World Z coordinate (depth / forward distance)
475	 * @returns {{x:number, y:number, scale:number}}
476	 */
477	R.worldToScreen=function(wx,wy,wz){var cam=R.camera;if(!cam)return{x:wx,y:wy,scale:1};var zoom=cam.zoom||1;var sx=R.CONFIG.CANVAS_WIDTH/2+(wx-(cam.x||0))*zoom;var sy=R.CONFIG.CANVAS_HEIGHT/2+(wy-(cam.y||0))*zoom;return{x:sx,y:sy,scale:zoom};};
478	
479	/* ==========================================================================
480	   R.renderSky(ctx) — Sky gradient and horizon
481	   ========================================================================== */
482	
483	/**
484	 * Draws a full-screen sky gradient from a darker top colour to a lighter
485	 * horizon colour, followed by a narrow ground/horizon strip.
486	 *
487	 * Operates in screen space: saves the current transform, resets to identity,
488	 * draws the sky, and restores.
489	 *
490	 * @param {CanvasRenderingContext2D} ctx
491	 */
492	R.renderSky = function (ctx) {
493	  var W = R.CONFIG.CANVAS_WIDTH;
494	  var H = R.CONFIG.CANVAS_HEIGHT;
495	  var horizonY = R.CONFIG.HORIZON_Y || 200;
496	
497	  ctx.save();
498	  ctx.setTransform(1, 0, 0, 1, 0, 0);
499	
500	  // ── Sky gradient ─────────────────────────────────────────────────────
501	  var skyTop    = R.CONFIG.SKY_TOP_COLOR    || '#1a1a2e';
502	  var skyBottom = R.CONFIG.SKY_BOTTOM_COLOR || '#87CEEB';
503	  var grad = ctx.createLinearGradient(0, 0, 0, horizonY + 40);
504	  grad.addColorStop(0,    skyTop);
505	  grad.addColorStop(0.65, '#4a6fa5');
506	  grad.addColorStop(1,    skyBottom);
507	  ctx.fillStyle = grad;
508	  ctx.fillRect(0, 0, W, horizonY + 40);
509	
510	  // ── Horizon glow ─────────────────────────────────────────────────────
511	  var glowGrad = ctx.createLinearGradient(0, horizonY - 20, 0, horizonY + 40);
512	  glowGrad.addColorStop(0, 'rgba(255,255,255,0)');
513	  glowGrad.addColorStop(0.5, 'rgba(255,255,255,0.15)');
514	  glowGrad.addColorStop(1, 'rgba(255,255,255,0)');
515	  ctx.fillStyle = glowGrad;
516	  ctx.fillRect(0, horizonY - 20, W, 60);
517	
518	  // ── Ground strip below horizon ───────────────────────────────────────
519	  var groundGrad = ctx.createLinearGradient(0, horizonY + 20, 0, H);
520	  groundGrad.addColorStop(0,    '#6b8c5c');  // distant green-brown
521	  groundGrad.addColorStop(0.15, '#5a7a4a');
522	  groundGrad.addColorStop(0.5,  R.CONFIG.TRACK_BG_COLOR || '#3a5a2c');
523	  groundGrad.addColorStop(1,    '#2a4a1c');
524	  ctx.fillStyle = groundGrad;
525	  ctx.fillRect(0, horizonY + 20, W, H - horizonY - 20);
526	
527	  // ── Horizon line ─────────────────────────────────────────────────────
528	  ctx.strokeStyle = 'rgba(255,255,255,0.25)';
529	  ctx.lineWidth   = 1;
530	  ctx.beginPath();
531	  ctx.moveTo(0, horizonY + 20);
532	  ctx.lineTo(W, horizonY + 20);
533	  ctx.stroke();
534	
535	  ctx.restore();
536	};
