538	/* ==========================================================================
539	   R.renderTrack(ctx) — Main track rendering
540	   ========================================================================== */
541	
542	/**
543	 * Renders the racing track with pseudo-3D perspective.
544	 *
545	 * Drawing order: back-to-front (far segments first) for correct occlusion.
546	 * For each consecutive segment pair, draws:
547	 *   1. Road surface trapezoid
548	 *   2. Edge lines (solid white)
549	 *   3. Centre dashed lane markings
550	 *   4. Red/white curbs on tight curves
551	 *
552	 * Operates in screen space: saves the camera transform, resets to identity,
553	 * does perspective projection via worldToScreen, then restores.
554	 *
555	 * @param {CanvasRenderingContext2D} ctx
556	 */
557	R.renderTrack = function (ctx) {
558	  var segs   = R.track.segments;
559	  var n      = segs.length;
560	  var total  = R.track.totalLength;
561	  var cam    = R.camera;
562	  var cfg    = R.CONFIG;
563	  var W      = cfg.CANVAS_WIDTH;
564	  var H      = cfg.CANVAS_HEIGHT;
565	
566	  if (!n) return;
567	
568	  // ── Update camera track position from player ────────────────────────
569	  if (R.player) {
570	    cam.worldZ = R.player.z;
571	    // Compute camera's approximate track distance for forward-distance calc
572	    var playerSegIdx = 0;
573	    var bestD2 = Infinity;
574	    for (var pidx = 0; pidx < n; pidx++) {
575	      var pseg = segs[pidx];
576	      var pdx  = pseg.worldX - R.player.x;
577	      var pdz  = pseg.worldZ - R.player.z;
578	      var pd2  = pdx * pdx + pdz * pdz;
579	      if (pd2 < bestD2) { bestD2 = pd2; playerSegIdx = pidx; }
580	    }
581	    cam.trackDist = segs[playerSegIdx].dist;
582	  } else {
583	    cam.worldZ    = cam.worldZ || 0;
584	    cam.trackDist = cam.trackDist || 0;
585	  }
586	
587	  // ── Save canvas state, reset to identity for screen-space drawing ───
588	  ctx.save();
589	  ctx.setTransform(1, 0, 0, 1, 0, 0);
590	
591	  var renderDist = cfg.RENDER_DISTANCE;
592	  var horY       = cfg.HORIZON_Y;
593	  var camDist    = cam.trackDist;
594	
595	  // ── Collect visible segments with computed screen positions ──────────
596	  var visible = [];
597	  for (var i = 0; i < n; i++) {
598	    var seg = segs[i];
599	    var dz  = _forwardDist(seg.dist, camDist, total);
600	
601	    // Cull segments too far behind or ahead
602	    if (dz < -renderDist || dz > renderDist * 1.4) continue;
603	
604	    // Compute screen position via perspective projection
605	    var proj = _projectSegment(seg, dz, cam, cfg, W, H);
606	
607	    // Cull segments off-screen
608	    if (proj.y > H + 100 || proj.y < -100) continue;
609	
610	    visible.push({
611	      index: i,
612	      seg:   seg,
613	      dz:    dz,
614	      sx:    proj.x,
615	      sy:    proj.y,
616	      scale: proj.scale,
617	      lx:    proj.lx,
618	      rx:    proj.rx
619	    });
620	  }
621	
622	  if (visible.length === 0) { ctx.restore(); return; }
623	
624	  // Sort far-to-near (back-to-front) for painter's algorithm
625	  visible.sort(function (a, b) { return b.dz - a.dz; });
626	
627	  // ── Draw terrain / grass beneath the road ─────────────────────────────
628	  // (A solid fill from horizon down, over which the road trapezoids sit)
629	  ctx.fillStyle = cfg.TRACK_BG_COLOR || '#3a5a2c';
630	  ctx.fillRect(0, horY + 20, W, H - horY - 20);
631	
632	  // ── Build a set of visible indices for fast pair-check ────────────────
633	  var visSet = {};
634	  for (var vi = 0; vi < visible.length; vi++) {
635	    visSet[visible[vi].index] = vi;
636	  }
637	
638	  // ── Track drawn-pair set to avoid double-drawing ─────────────────────
639	  var drawnPairs = {};
640	
641	  // ── Pass 1: Road surface trapezoids ──────────────────────────────────
642	  for (var vi2 = 0; vi2 < visible.length; vi2++) {
643	    var cur  = visible[vi2];
644	    var idx  = cur.index;
645	    var nextIdx = (idx + 1) % n;
646	
647	    // Only draw if the next segment is also visible
648	    if (!(nextIdx in visSet)) continue;
649	
650	    // Avoid double-draw: each pair is drawn when processing the farther segment
651	    var pairKey = idx + '_' + nextIdx;
652	    if (drawnPairs[pairKey]) continue;
653	    drawnPairs[pairKey] = true;
654	
655	    var nxtVis = visible[visSet[nextIdx]];
656	    // Use the stored screen coordinates
657	    var clx = cur.lx, crx = cur.rx, csy = cur.sy;
658	    var nlx = nxtVis.lx, nrx = nxtVis.rx, nsy = nxtVis.sy;
659	
660	    // ── Road surface colour (slight variation per segment) ─────────────
661	    var baseColor = cfg.ROAD_COLOR || '#555';
662	    var colorVar  = ((idx * 17) & 7) - 3; // pseudo-random ±3 per segment
663	    var rgb = _adjustBrightness(baseColor, colorVar);
664	    ctx.fillStyle = rgb;
665	
666	    // Draw the trapezoid: (clx,csy) → (crx,csy) → (nrx,nsy) → (nlx,nsy)
667	    ctx.beginPath();
668	    ctx.moveTo(clx, csy);
669	    ctx.lineTo(crx, csy);
670	    ctx.lineTo(nrx, nsy);
671	    ctx.lineTo(nlx, nsy);
672	    ctx.closePath();
673	    ctx.fill();
674	
675	    // ── Edge lines ─────────────────────────────────────────────────────
676	    ctx.strokeStyle = cfg.LINE_COLOR || '#fff';
677	    ctx.lineWidth   = Math.max(cur.scale * 2.5, 1);
678	    ctx.beginPath();
679	    ctx.moveTo(clx, csy);
680	    ctx.lineTo(nlx, nsy);
681	    ctx.stroke();
682	
683	    ctx.beginPath();
684	    ctx.moveTo(crx, csy);
685	    ctx.lineTo(nrx, nsy);
686	    ctx.stroke();
687	
688	    // ── Curbs on tight curves ──────────────────────────────────────────
689	    if (Math.abs(cur.seg.curvature) > (cfg.CURB_CURVATURE_THRESH || 0.0012)) {
690	      var curbW  = cfg.RUMBLE_WIDTH || 6;
691	      var curbScale = Math.max(cur.scale * curbW, 1);
692	      var isOuterRight = cur.seg.curvature < 0; // negative curvature = right turn, outer = left
693	
694	      if (isOuterRight) {
695	        // Outer curb is on the left edge (outside of a right turn)
696	        _drawCurbSegment(ctx, clx, csy, nlx, nsy, curbScale, cur.dz, cfg);
697	      } else {
698	        // Outer curb is on the right edge (outside of a left turn)
699	        _drawCurbSegment(ctx, crx, csy, nrx, nsy, curbScale, cur.dz, cfg);
700	      }
701	    }
702	  }
703	
704	  // ── Pass 2: Centre lane markings ─────────────────────────────────────
705	  _drawLaneMarkings(ctx, visible, cfg, total);
706	
707	  ctx.restore();
708	};
709	
710	/* ==========================================================================
711	   RENDERING HELPERS
712	   ========================================================================== */
713	
714	/**
715	 * Projects a single track segment to screen coordinates.
716	 * Returns the centre screen position plus left/right edge positions.
717	 *
718	 * @param {Object} seg Segment object
719	 * @param {number} dz  Forward distance from camera (signed)
720	 * @param {Object} cam Camera object
721	 * @param {Object} cfg CONFIG object
722	 * @param {number} W   Canvas width
723	 * @param {number} H   Canvas height
724	 * @returns {{x:number, y:number, scale:number, lx:number, rx:number}}
725	 */
726	function _projectSegment(seg, dz, cam, cfg, W, H) {
727	  var coeff    = cfg.PERSPECTIVE_COEFF;
728	  var absDz    = dz < 0 ? -dz : dz;
729	  var scale    = cam.zoom / (1 + absDz * coeff);
730	
731	  // Screen centre X — horizontal displacement from camera
732	  var dx   = seg.worldX - cam.x;
733	  var sx   = W / 2 + dx * scale;
734	
735	  // Screen centre Y — incorporates elevation and forward distance
736	  // dz > 0 (ahead) → smaller sy (higher on screen, toward horizon)
737	  // dz < 0 (behind) → larger sy (lower on screen)
738	  var dy   = seg.worldY - cam.y;
739	  var sy   = H / 2 + dy * scale - dz * cfg.ROAD_V_OFFSET * scale;
740	
741	  // Left/right edge screen positions
742	  var halfW = seg.width / 2;
743	  // Left edge: offset perpendicular to segment direction
744	  var cosA = Math.cos(seg.angle);
745	  var sinA = Math.sin(seg.angle);
746	  // Left = direction * halfWidth rotated 90° counter-clockwise
747	  var leftDx  = dx + cosA * halfW;
748	  var rightDx = dx - cosA * halfW;
749	  // Screen X for edges (same Y as centre, same scale)
750	  var lx = W / 2 + leftDx  * scale;
751	  var rx = W / 2 + rightDx * scale;
752	
753	  return { x: sx, y: sy, scale: scale, lx: lx, rx: rx };
754	}
755	
756	/**
757	 * Draws a single curb stripe segment between two screen-space points.
758	 * Alternates red/white based on distance along the track.
759	 *
760	 * @param {CanvasRenderingContext2D} ctx
761	 * @param {number} x1  Start X on screen
762	 * @param {number} y1  Start Y on screen
763	 * @param {number} x2  End X on screen
764	 * @param {number} y2  End Y on screen
765	 * @param {number} w   Curb width in screen pixels
766	 * @param {number} dz  Forward distance (for stripe index)
767	 * @param {Object} cfg CONFIG
768	 */
769	function _drawCurbSegment(ctx, x1, y1, x2, y2, w, dz, cfg) {
770	  var stripeLen = 25; // world units per stripe
771	  var idx = Math.floor(Math.abs(dz) / stripeLen);
772	  var color = (idx % 2 === 0) ? (cfg.RUMBLE_COLOR_A || '#ff0000')
773	                              : (cfg.RUMBLE_COLOR_B || '#ffffff');
774	  ctx.strokeStyle = color;
775	  ctx.lineWidth   = Math.max(w, 1.5);
776	  ctx.beginPath();
777	  ctx.moveTo(x1, y1);
778	  ctx.lineTo(x2, y2);
779	  ctx.stroke();
780	}
781	
782	/**
783	 * Draws dashed centre-line markings across visible road segments.
784	 *
785	 * @param {CanvasRenderingContext2D} ctx
786	 * @param {Array}  visible Array of visible segment entries (sorted far→near)
787	 * @param {Object} cfg     CONFIG
788	 * @param {number} total   Total track length
789	 */
790	function _drawLaneMarkings(ctx, visible, cfg, total) {
791	  var dashLen  = cfg.LANE_MARKER_DASH || 40;
792	  var gapLen   = cfg.LANE_MARKER_GAP  || 30;
793	  var cycleLen = dashLen + gapLen;
794	
795	  ctx.strokeStyle = cfg.LANE_MARKER_COLOR || '#ccc';
796	
797	  for (var vi = 0; vi < visible.length; vi++) {
798	    var cur = visible[vi];
799	    var seg = cur.seg;
800	    var d   = seg.dist;
801	
802	    // Determine if this segment is in a dash or gap
803	    var cyclePos = d % cycleLen;
804	    if (cyclePos < 0) cyclePos += cycleLen;
805	    if (cyclePos >= dashLen) continue; // gap — skip
806	
807	    var lineW = Math.max(cur.scale * (cfg.LANE_MARKER_WIDTH || 1.5), 0.6);
808	    ctx.lineWidth = lineW;
809	
810	    // Draw from centre position of this segment toward next
811	    // Use a short dash at the segment centre
812	    var dashScreenLen = Math.max(cur.scale * dashLen * 0.3, 3);
813	    var angle = seg.angle;
814	    var cosA  = Math.cos(angle);
815	    var sinA  = Math.sin(angle);
816	    // Forward direction in screen space (from the centre point)
817	    var fx = sinA * cur.scale * 8; // forward component projected to screen X
818	    var fy = -cfg.ROAD_V_OFFSET * cur.scale * 8; // forward component in screen Y
819	
820	    ctx.beginPath();
821	    ctx.moveTo(cur.sx - fx, cur.sy - fy);
822	    ctx.lineTo(cur.sx + fx, cur.sy + fy);
823	    ctx.stroke();
824	  }
825	}
826	
827	/**
828	 * Adjusts a hex colour string's brightness by a signed integer amount.
829	 * Preserves the colour format (#xxx or #xxxxxx).
830	 *
831	 * @param {string} hex    Hex colour (e.g. '#555')
832	 * @param {number} amount Signed adjustment (-255 to 255)
833	 * @returns {string} Adjusted hex colour
834	 */
835	function _adjustBrightness(hex, amount) {
836	  if (hex.charAt(0) === '#') hex = hex.slice(1);
837	  if (hex.length === 3) {
838	    hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
839	  }
840	  var r = Math.min(255, Math.max(0, parseInt(hex.slice(0, 2), 16) + amount));
841	  var g = Math.min(255, Math.max(0, parseInt(hex.slice(2, 4), 16) + amount));
842	  var b = Math.min(255, Math.max(0, parseInt(hex.slice(4, 6), 16) + amount));
843	  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
844	}
845	
846	/* ==========================================================================
847	   R.getTrackDistanceAt(wx, wz) — Utility for AI / position tracking
848	   ========================================================================== */
849	
850	/**
851	 * Returns the cumulative track distance of the nearest point on the track
852	 * centre-line to the given world position. Useful for AI lap tracking.
853	 *
854	 * @param {number} wx World X coordinate
855	 * @param {number} wz World Z coordinate
856	 * @returns {number} Track distance at nearest centre-line point
857	 */
858	R.getTrackDistanceAt = function (wx, wz) {
859	  var segs  = R.track.segments;
860	  var n     = segs.length;
861	  var bestIdx   = 0;
862	  var bestDist2 = Infinity;
863	  for (var i = 0; i < n; i++) {
864	    var dx = segs[i].worldX - wx;
865	    var dz = segs[i].worldZ - wz;
866	    var d2 = dx * dx + dz * dz;
867	    if (d2 < bestDist2) {
868	      bestDist2 = d2;
869	      bestIdx   = i;
870	    }
871	  }
872	  return segs[bestIdx].dist;
873	};
874	
875	/* ==========================================================================
876	   R.getSegmentAtDistance(dist) — Direct segment access
877	   ========================================================================== */
878	
879	/**
880	 * Returns the segment object at a given track distance (no interpolation).
881	 * Wraps around for closed circuit.
882	 *
883	 * @param {number} dist Cumulative track distance
884	 * @returns {Object} The segment at that distance
885	 */
886	R.getSegmentAtDistance = function (dist) {
887	  var segs  = R.track.segments;
888	  var total = R.track.totalLength;
889	  var n     = segs.length;
890	  var d     = dist % total;
891	  if (d < 0) d += total;
892	
893	  var lo = 0, hi = n - 1;
894	  while (lo < hi) {
895	    var mid = (lo + hi + 1) >> 1;
896	    if (segs[mid].dist <= d) lo = mid;
897	    else hi = mid - 1;
898	  }
899	  return segs[lo];
900	};
901	
902	/* ==========================================================================
903	   R.getTrackWidth(dist) — Quick width lookup (AI avoidance)
904	   ========================================================================== */
905	
906	/**
907	 * Returns the interpolated road width at a given track distance.
908	 * Convenience wrapper for AI / collision systems.
909	 *
910	 * @param {number} dist Cumulative track distance
911	 * @returns {number} Road width in world units
912	 */
913	R.getTrackWidth = function (dist) {
914	  var pos = R.getTrackPosition(dist);
915	  return pos.width;
916	};
917	
918	/* ==========================================================================
919	   R.isOnTrackExtended(wx, wy, wz) — Full 3D collision check
920	   ========================================================================== */
921	
922	/**
923	 * Extended on-track check that also verifies elevation proximity.
924	 * Useful for respawn logic or when cars go airborne (future).
925	 * Falls back to 2D check if worldY is unavailable.
926	 *
927	 * @param {number} wx World X
928	 * @param {number} wy World Y (elevation)
929	 * @param {number} wz World Z
930	 * @returns {{onTrack:boolean, distFromCenter:number, segmentIndex:number, elevationOk:boolean}}
931	 */
932	R.isOnTrackExtended = function (wx, wy, wz) {
933	  var result = R.isOnTrack(wx, wz);
934	
935	  if (!result.onTrack) return result;
936	
937	  // Check elevation proximity
938	  var seg       = R.track.segments[result.segmentIndex];
939	  var elevDiff  = Math.abs(wy - seg.worldY);
940	  var elevOk    = elevDiff < 80; // within 80 world units of segment elevation
941	
942	  return {
943	    onTrack:        result.onTrack && elevOk,
944	    distFromCenter: result.distFromCenter,
945	    segmentIndex:   result.segmentIndex,
946	    halfWidth:      result.halfWidth,
947	    elevationOk:    elevOk
948	  };
949	};
950	
951	/* ==========================================================================
952	   EXPORTS
953	   ==========================================================================
954	   Attached to window.R:
955	     R.initTrack()            — Generate closed-loop racing circuit
956	     R.getTrackPosition()     — Interpolated position lookup by distance
957	     R.isOnTrack()            — 2D on-track collision check
958	     R.isOnTrackExtended()    — 3D on-track check with elevation
959	     R.worldToScreen()        — Perspective world-to-screen projection
960	     R.renderSky(ctx)         — Sky gradient + horizon rendering
961	     R.renderTrack(ctx)       — Pseudo-3D road surface rendering
962	     R.getTrackDistanceAt()   — Nearest centre-line distance for a point
963	     R.getSegmentAtDistance() — Direct segment access
964	     R.getTrackWidth()        — Quick interpolated width lookup
965	
966	   Populated data:
967	     R.track.segments[]       — Array of track segment objects
968	     R.track.totalLength      — Total track length in world units
969	     R.track.totalLaps        — Number of laps (from CONFIG)
970	     R.track.startX/Y/Z       — Spawn position (segment[0])
971	     R.track.startAngle       — Spawn facing direction
972	     R.track.checkpoints[]    — Evenly-spaced checkpoint positions
973	
974	   Extended CONFIG keys (merged into R.CONFIG):
975	     TRACK_CONTROL_POINTS, TRACK_SEGMENTS_PER_CP, TRACK_BASE_RADIUS,
976	     TRACK_RADIUS_VAR1/2/3, TRACK_RADIUS_JITTER, ROAD_WIDTH_MIN,
977	     CURB_CURVATURE_THRESH, HILL_AMPLITUDE_A/B, HILL_FREQ_A/B,
978	     HILL_PHASE_B, RENDER_DISTANCE, RENDER_FADE_NEAR, HORIZON_Y,
979	     PERSPECTIVE_COEFF, ROAD_V_OFFSET, SEGMENT_COLOR_VAR,
980	     TRACK_BG_COLOR, TRACK_BG_COLOR_FAR, SHOULDER_COLOR
981	   ========================================================================== */
982	// === track.js — Racing Game ===
