1	// === player.js — Racing Game ===
2	// Player car: physics simulation, rendering, checkpoint/lap logic.
3	// All functions attach to window.R. Assumes R.CONFIG, R.canvas, R.ctx,
4	// R.input, R.camera, R.track, and R.state already exist.
5	
6	/* ==========================================================================
7	   CONFIG defaults (merged into R.CONFIG if keys are missing)
8	   ========================================================================== */
9	(function ensurePlayerConfig() {
10	  const defaults = {
11	
12	    // ── Car physics ──────────────────────────────────────────────────
13	    MAX_SPEED:           12,        // px/frame at 60 fps (~720 px/s)
14	    ACCELERATION:        0.08,      // speed += accel * dt * 60
15	    BRAKING:             0.14,      // speed -= brake * dt * 60
16	    FRICTION:            0.985,     // multiplicative per-frame drag
17	    HANDLING:            0.045,     // steer sensitivity
18	    MAX_STEER:           0.6,       // radians, clamp
19	    STEER_CENTER_RATE:   0.85,      // per-frame self-centering
20	    DRIFT_FACTOR:        0.92,      // forward friction while drifting
21	    DRIFT_THRESHOLD:     0.15,      // drift magnitude to trigger
22	    OFFROAD_FRICTION:    0.92,      // multiplicative when off track
23	    BOOST_MULTIPLIER:    1.6,       // speed multiplier during boost
24	    BOOST_DURATION:      1.5,       // seconds
25	    BOOST_COOLDOWN:      3.0,       // seconds
26	
27	    // ── Car dimensions (pixels in world space) ───────────────────────
28	    CAR_LENGTH:          48,
29	    CAR_WIDTH:           24,
30	    WHEELBASE:           30,        // axle-to-axle distance
31	    WHEEL_WIDTH:         7,
32	    WHEEL_LENGTH:        12,
33	
34	    // ── Rendering ────────────────────────────────────────────────────
35	    SHADOW_OFFSET_X:     4,
36	    SHADOW_OFFSET_Y:     2,
37	    SHADOW_ALPHA:        0.35,
38	    WINDSHIELD_RATIO:    0.22,      // portion of car length
39	    REAR_WINDOW_RATIO:   0.18,
40	    DOOR_LINE_OFFSET:    0.38,      // door gap from front
41	    STRIPE_WIDTH:        4,
42	    EXHAUST_BASE_WIDTH:  8,
43	    EXHAUST_LENGTH:      14,
44	    DRIFT_MARK_LIFETIME: 0.6,       // seconds visible
45	    DRIFT_MARK_SPACING:  5,         // px between marks
46	
47	    // ── Checkpoints ──────────────────────────────────────────────────
48	    CHECKPOINT_PROXIMITY: 60,       // px — how close counts as "passed"
49	    TOTAL_LAPS:          3,
50	  };
51	
52	  R.CONFIG = R.CONFIG || {};
53	  for (const k in defaults) {
54	    if (!(k in R.CONFIG)) R.CONFIG[k] = defaults[k];
55	  }
56	})();
57	
58	/* ==========================================================================
59	   DRIFT MARK POOL — pre-allocated circular buffer
60	   ========================================================================== */
61	const DRIFT_MARK_CAPACITY = 80;
62	const driftMarks = new Array(DRIFT_MARK_CAPACITY);
63	for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) {
64	  driftMarks[i] = { x: 0, y: 0, alpha: 0, age: 0, alive: false };
65	}
66	let driftMarkWriteIdx = 0;
67	
68	function spawnDriftMark(x, y) {
69	  const m = driftMarks[driftMarkWriteIdx];
70	  m.x = x;
71	  m.y = y;
72	  m.alpha = 0.55;
73	  m.age = 0;
74	  m.alive = true;
75	  driftMarkWriteIdx = (driftMarkWriteIdx + 1) % DRIFT_MARK_CAPACITY;
76	}
77	
78	/* ==========================================================================
79	   EXHAUST PARTICLE POOL
80	   ========================================================================== */
81	const EXHAUST_CAPACITY = 24;
82	const exhaustParticles = new Array(EXHAUST_CAPACITY);
83	for (let i = 0; i < EXHAUST_CAPACITY; i++) {
84	  exhaustParticles[i] = { x: 0, y: 0, vx: 0, vy: 0, life: 0, maxLife: 0, size: 0, alive: false };
85	}
86	let exhaustWriteIdx = 0;
87	
88	function spawnExhaustParticle(x, y, angle) {
89	  const p = exhaustParticles[exhaustWriteIdx];
90	  const spread = (Math.random() - 0.5) * 0.5;
91	  const dir = angle + Math.PI + spread;
92	  const spd = 1.5 + Math.random() * 3;
93	  p.x = x;
94	  p.y = y;
95	  p.vx = Math.cos(dir) * spd;
96	  p.vy = Math.sin(dir) * spd;
97	  p.life = 0.25 + Math.random() * 0.35;
98	  p.maxLife = p.life;
99	  p.size = 3 + Math.random() * 4;
100	  p.alive = true;
101	  exhaustWriteIdx = (exhaustWriteIdx + 1) % EXHAUST_CAPACITY;
102	}
103	
104	/* ==========================================================================
105	   BOUNCE-BACK MARKERS (visual feedback for collisions)
106	   ========================================================================== */
107	const BOUNCE_CAPACITY = 8;
108	const bounceMarkers = new Array(BOUNCE_CAPACITY);
109	for (let i = 0; i < BOUNCE_CAPACITY; i++) {
110	  bounceMarkers[i] = { x: 0, y: 0, radius: 0, alpha: 0, alive: false };
111	}
112	let bounceWriteIdx = 0;
113	
114	function spawnBounceMarker(x, y) {
115	  const m = bounceMarkers[bounceWriteIdx];
116	  m.x = x;
117	  m.y = y;
118	  m.radius = 14;
119	  m.alpha = 0.7;
120	  m.alive = true;
121	  bounceWriteIdx = (bounceWriteIdx + 1) % BOUNCE_CAPACITY;
122	}
123	
124	/* ==========================================================================
125	   R.initPlayer()
126	   Create the player car at the track start position.
127	   ========================================================================== */
128	R.initPlayer = function initPlayer() {
129	  const cfg = R.CONFIG;
130	  const seg0 = (R.track && R.track.segments && R.track.segments.length)
131	    ? R.track.segments[0]
132	    : { worldX: 0, worldY: 0, worldZ: 0 };
133	
134	  R.player = {
135	    // ── World position ─────────────────────────────────────────────
136	    x:        seg0.worldX || 0,
137	    y:        seg0.worldY || 0,
138	    z:        0,                         // distance along track
139	
140	    // ── Motion ─────────────────────────────────────────────────────
141	    angle:    0,                         // radians, 0 = right
142	    speed:    0,
143	    steerAngle: 0,
144	
145	    // ── Drift state ────────────────────────────────────────────────
146	    driftFactor: 0,
147	    isDrifting: false,
148	
149	    // ── Boost ──────────────────────────────────────────────────────
150	    boosting:       false,
151	    boostTimer:     0,
152	    boostCooldown:  0,
153	
154	    // ── Lap / checkpoint ───────────────────────────────────────────
155	    lap:           0,
156	    checkpointIdx: 0,
157	    finished:      false,
158	
159	    // ── Visual ─────────────────────────────────────────────────────
160	    color:       '#00ff88',
161	    accentColor: '#00cc66',
162	    wheelRot:    0,                      // accumulated wheel rotation
163	
164	    // ── Physics constants (per-player copy for potential tuning) ───
165	    maxSpeed:     cfg.MAX_SPEED,
166	    acceleration: cfg.ACCELERATION,
167	    braking:      cfg.BRAKING,
168	    handling:     cfg.HANDLING,
169	  };
170	
171	  // Reset drift marks
172	  for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) {
173	    driftMarks[i].alive = false;
174	  }
175	  // Reset exhaust
176	  for (let i = 0; i < EXHAUST_CAPACITY; i++) {
177	    exhaustParticles[i].alive = false;
178	  }
179	  // Reset bounce markers
180	  for (let i = 0; i < BOUNCE_CAPACITY; i++) {
181	    bounceMarkers[i].alive = false;
182	  }
183	};
184	
185	/* ==========================================================================
186	   R.updatePlayer(dt) — Full car physics simulation
187	   dt = delta time in seconds (unscaled)
188	   ========================================================================== */
189	R.updatePlayer = function updatePlayer(dt) {
190	  const p  = R.player;
191	  if (!p || p.finished) return;
192	
193	  const cfg  = R.CONFIG;
194	  const inp  = R.input;
195	
196	  // Clamp dt to avoid huge jumps (tab-away recovery)
197	  const dtClamped = Math.min(dt, 0.05);
198	  // Scale factor: physics tuned at 60 fps, so multiply by dt*60
199	  const f = dtClamped * 60;
200	
201	  // ── 1. STEERING ──────────────────────────────────────────────────
202	  const steerInput = inp.steer || 0;               // -1..0..1
203	
204	  // Speed-sensitive steering (tighter at low speed, wider at high)
205	  const speedRatio = p.speed / p.maxSpeed;
206	  const steerResponse = cfg.HANDLING * (1 + speedRatio * 0.5);
207	  p.steerAngle += steerInput * steerResponse * f;
208	
209	  // Self-centering (stronger when no input)
210	  if (Math.abs(steerInput) < 0.05) {
211	    p.steerAngle *= Math.pow(cfg.STEER_CENTER_RATE, f);
212	  } else {
213	    p.steerAngle *= Math.pow(cfg.STEER_CENTER_RATE * 0.97, f);
214	  }
215	
216	  // Clamp
217	  if (p.steerAngle > cfg.MAX_STEER) p.steerAngle = cfg.MAX_STEER;
218	  if (p.steerAngle < -cfg.MAX_STEER) p.steerAngle = -cfg.MAX_STEER;
219	
220	  // ── 2. ACCELERATION / BRAKING ────────────────────────────────────
221	  const throttle = inp.throttle || 0;
222	  const brake    = inp.brake    || 0;
223	  const boost    = inp.boost    || 0;
224	
225	  // Boost activation
226	  if (boost && !p.boosting && p.boostCooldown <= 0 && p.speed > 0.5) {
227	    p.boosting     = true;
228	    p.boostTimer   = cfg.BOOST_DURATION;
229	    p.boostCooldown = cfg.BOOST_COOLDOWN + cfg.BOOST_DURATION;
230	  }
231	
232	  // Boost timer
233	  if (p.boosting) {
234	    p.boostTimer -= dt;
235	    if (p.boostTimer <= 0) {
236	      p.boosting   = false;
237	      p.boostTimer = 0;
238	    }
239	  }
240	
241	  // Boost cooldown
242	  if (p.boostCooldown > 0 && !p.boosting) {
243	    p.boostCooldown -= dt;
244	    if (p.boostCooldown < 0) p.boostCooldown = 0;
245	  }
246	
247	  // Apply acceleration
248	  if (throttle && !brake) {
249	    let accel = p.acceleration * f;
250	    if (p.boosting) accel *= cfg.BOOST_MULTIPLIER;
251	    p.speed += accel;
252	
253	    // Low-speed extra torque for startup feel
254	    if (p.speed < 1.0) {
255	      p.speed += accel * 0.5;
256	    }
257	  }
258	
259	  if (brake) {
260	    p.speed -= p.braking * f;
261	  }
262	
263	  // Friction (natural deceleration)
264	  p.speed *= Math.pow(cfg.FRICTION, f);
265	
266	  // Clamp speed (allow slight overshoot from boost)
267	  const maxNow = p.boosting ? p.maxSpeed * cfg.BOOST_MULTIPLIER : p.maxSpeed;
268	  if (p.speed < 0)    p.speed = 0;
269	  if (p.speed > maxNow) p.speed = maxNow;
270	
271	  // ── 3. DRIFT ─────────────────────────────────────────────────────
272	  const lateralForce = p.speed * p.steerAngle * 0.3 * f;
273	  p.driftFactor += (lateralForce - p.driftFactor) * 0.1 * f;
274	  const driftMagnitude = Math.abs(p.driftFactor);
275	  const wasDrifting = p.isDrifting;
276	  p.isDrifting = driftMagnitude > cfg.DRIFT_THRESHOLD;
277	
278	  // ── 4. POSITION UPDATE ───────────────────────────────────────────
279	  const effectiveAngle = p.angle + p.driftFactor * 0.5;
280	  const forwardFriction = p.isDrifting
281	    ? Math.pow(cfg.DRIFT_FACTOR, f)
282	    : 1.0;
283	
284	  p.x += Math.cos(p.angle) * p.speed * Math.cos(p.driftFactor) * forwardFriction * f;
285	  p.y += Math.sin(p.angle) * p.speed * Math.cos(p.driftFactor) * forwardFriction * f;
286	  p.angle += p.steerAngle * p.speed * 0.03 * f;
287	
288	  // Keep angle in [0, 2π)
289	  while (p.angle < 0)            p.angle += Math.PI * 2;
290	  while (p.angle >= Math.PI * 2) p.angle -= Math.PI * 2;
291	
292	  // Accumulate wheel rotation (for visual)
293	  p.wheelRot += p.speed * 0.06 * f;
294	
295	  // ── 5. TRACK CHECK ───────────────────────────────────────────────
296	  if (R.isOnTrack && typeof R.isOnTrack === 'function') {
297	    if (!R.isOnTrack(p.x, p.z)) {
298	      p.speed *= Math.pow(cfg.OFFROAD_FRICTION, f);
299	    }
300	  }
301	
302	  // ── 6. LAP / CHECKPOINT LOGIC ────────────────────────────────────
303	  if (R.track && R.track.segments && R.track.segments.length) {
304	    const segs = R.track.segments;
305	    const totalCheckpoints = segs.length;
306	
307	    // Current checkpoint target
308	    const targetSeg = segs[p.checkpointIdx % totalCheckpoints];
309	    if (targetSeg) {
310	      const dx = p.x - (targetSeg.worldX || 0);
311	      const dy = p.y - (targetSeg.worldY || 0);
312	      const dist = Math.sqrt(dx * dx + dy * dy);
313	
314	      if (dist < cfg.CHECKPOINT_PROXIMITY) {
315	        p.checkpointIdx++;
316	
317	        // Completed a full lap?
318	        if (p.checkpointIdx >= totalCheckpoints) {
319	          p.lap++;
320	          p.checkpointIdx = 0;
321	
322	          if (p.lap >= cfg.TOTAL_LAPS) {
323	            p.finished = true;
324	            p.speed = 0;
325	            R.state.phase = 'finished';
326	          }
327	        }
328	      }
329	    }
330	  }
331	
332	  // ── 7. Store z as total distance traveled ────────────────────────
333	  p.z += p.speed * f;
334	
335	  // ── 8. Drift marks (spawn every few pixels when drifting) ────────
336	  if (p.isDrifting && p.speed > 1.0) {
337	    const rearX = p.x - Math.cos(p.angle) * cfg.CAR_LENGTH * 0.4;
338	    const rearY = p.y - Math.sin(p.angle) * cfg.CAR_LENGTH * 0.4;
339	    const perpX = Math.cos(p.angle + Math.PI / 2);
340	    const perpY = Math.sin(p.angle + Math.PI / 2);
341	
342	    const trackOffset = cfg.CAR_WIDTH * 0.35;
343	    // Left rear
344	    spawnDriftMark(
345	      rearX + perpX * trackOffset,
346	      rearY + perpY * trackOffset
347	    );
348	    // Right rear
349	    spawnDriftMark(
350	      rearX - perpX * trackOffset,
351	      rearY - perpY * trackOffset
352	    );
353	  }
354	
355	  // ── 9. Exhaust particles ─────────────────────────────────────────
356	  if (throttle && p.speed > 0.3) {
357	    const rearX = p.x - Math.cos(p.angle) * cfg.CAR_LENGTH * 0.5;
358	    const rearY = p.y - Math.sin(p.angle) * cfg.CAR_LENGTH * 0.5;
359	    // Per-tick rate: more particles at higher speed / boost
360	    const rate = p.boosting ? 0.55 : 0.3;
361	    if (Math.random() < rate * f) {
362	      spawnExhaustParticle(rearX, rearY, p.angle);
363	    }
364	  }
365	
366	  // ── 10. Update drift marks (age / fade) ──────────────────────────
367	  for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) {
368	    const m = driftMarks[i];
369	    if (!m.alive) continue;
370	    m.age += dt;
371	    if (m.age > cfg.DRIFT_MARK_LIFETIME) {
372	      m.alive = false;
373	    } else {
374	      m.alpha = 0.55 * (1 - m.age / cfg.DRIFT_MARK_LIFETIME);
375	    }
376	  }
377	
378	  // ── 11. Update exhaust particles ─────────────────────────────────
379	  for (let i = 0; i < EXHAUST_CAPACITY; i++) {
380	    const ep = exhaustParticles[i];
381	    if (!ep.alive) continue;
382	    ep.life -= dt;
383	    if (ep.life <= 0) {
384	      ep.alive = false;
385	    } else {
386	      ep.x += ep.vx * f;
387	      ep.y += ep.vy * f;
388	    }
389	  }
390	
391	  // ── 12. Update bounce markers ────────────────────────────────────
392	  for (let i = 0; i < BOUNCE_CAPACITY; i++) {
393	    const bm = bounceMarkers[i];
394	    if (!bm.alive) continue;
395	    bm.alpha -= dt * 2.5;
396	    bm.radius += dt * 60;
397	    if (bm.alpha <= 0) bm.alive = false;
398	  }
399	};
400	
401	/* ==========================================================================
402	   R.playerCollide(obstacleX, obstacleY, obstacleRadius)
403	   Called by collision system. Bounces player and spawns visual marker.
404	   Returns true if collision was processed.
405	   ========================================================================== */
406	R.playerCollide = function playerCollide(ox, oy, oRadius) {
407	  const p = R.player;
408	  if (!p) return false;
409	
410	  spawnBounceMarker(p.x, p.y);
411	
412	  // Push player away from obstacle center
413	  const dx = p.x - ox;
414	  const dy = p.y - oy;
415	  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
416	  const pushDist = (oRadius || 30) + R.CONFIG.CAR_WIDTH * 0.6;
417	  p.x = ox + (dx / dist) * pushDist;
418	  p.y = oy + (dy / dist) * pushDist;
419	
420	  // Kill speed
421	  p.speed *= 0.4;
422	  p.driftFactor *= 0.5;
423	
424	  return true;
425	};
426	
427	/* ==========================================================================
428	   WORLD → SCREEN HELPERS
429	   ========================================================================== */
430	
431	/**
432	 * Convert world coordinates to screen coordinates using camera.
433	 * @param {number} wx - world x
434	 * @param {number} wy - world y
435	 * @returns {{ sx: number, sy: number }}
436	 */
437	function worldToScreen(wx,wy){return R.worldToScreen(wx,wy);}
438	
439	/* ==========================================================================
440	   R.renderPlayerCar() — Detailed top-down car rendering
441	   Uses canvas transform stack (save/translate/rotate/restore).
442	   ========================================================================== */
443	R.renderPlayerCar = function renderPlayerCar() {
444	  const p = R.player;
445	  if (!p) return;
446	
447	  const cfg = R.CONFIG;
448	  const ctx = R.ctx;
449	  const cam = R.camera || { x: 0, y: 0, zoom: 1 };
450	  const zoom = cam.zoom;
451	
452	  // Convert world position to screen
453	  const screen = R.worldToScreen(p.x, p.y);
454	  const sx = screen.sx;
455	  const sy = screen.sy;
456	
457	  // Culling: skip if far off screen
458	  const W = (R.canvas && R.canvas.width)  || 1280;
459	  const H = (R.canvas && R.canvas.height) || 720;
460	  const margin = 200;
461	  if (sx < -margin || sx > W + margin || sy < -margin || sy > H + margin) return;
462	
463	  const carLen   = cfg.CAR_LENGTH   * zoom;
464	  const carHalfW = cfg.CAR_WIDTH    * 0.5 * zoom;
465	  const wheelLen = cfg.WHEEL_LENGTH * zoom;
466	  const wheelW   = cfg.WHEEL_WIDTH  * zoom;
467	  const wheelBase = cfg.WHEELBASE   * zoom;
468	
469	  ctx.save();
470	  ctx.translate(sx, sy);
471	  ctx.rotate(p.angle);
472	
473	  // ── 1. SHADOW ────────────────────────────────────────────────────
474	  const shadowOx = cfg.SHADOW_OFFSET_X * zoom;
475	  const shadowOy = cfg.SHADOW_OFFSET_Y * zoom;
476	  ctx.save();
477	  ctx.translate(shadowOx, shadowOy);
478	  ctx.fillStyle = `rgba(0, 0, 0, ${cfg.SHADOW_ALPHA})`;
479	  ctx.beginPath();
480	  ctx.ellipse(0, 0, carLen * 0.52, carHalfW * 1.15, 0, 0, Math.PI * 2);
481	  ctx.fill();
482	  ctx.restore();
483	
484	  // ── 2. CAR BODY ──────────────────────────────────────────────────
485	  // Main body — rounded rectangle
486	  const bodyFront  =  carLen * 0.5;
487	  const bodyRear   = -carLen * 0.5;
488	  const bodyRadius =  carHalfW * 0.55;
489	
490	  ctx.fillStyle = p.color;
491	  ctx.strokeStyle = p.accentColor;
492	  ctx.lineWidth = 2 * zoom;
493	  ctx.beginPath();
494	  roundedRect(ctx, bodyRear, -carHalfW, carLen, carHalfW * 2, bodyRadius);
495	  ctx.fill();
496	  ctx.stroke();
497	
498	  // Body panel lines — hood cut
499	  ctx.strokeStyle = 'rgba(255,255,255,0.12)';
500	  ctx.lineWidth = 1 * zoom;
501	  ctx.beginPath();
502	  ctx.moveTo(bodyFront * 0.65, -carHalfW * 0.85);
503	  ctx.lineTo(bodyFront * 0.65,  carHalfW * 0.85);
504	  ctx.stroke();
505	
506	  // ── 3. WINDSHIELD ────────────────────────────────────────────────
507	  const wsFront =  carLen * 0.5  - carLen * 0.06;
508	  const wsRear  =  carLen * 0.5  - carLen * cfg.WINDSHIELD_RATIO;
509	  ctx.fillStyle = 'rgba(20, 40, 60, 0.7)';
510	  ctx.beginPath();
511	  ctx.moveTo(wsFront, -carHalfW * 0.84);
512	  ctx.lineTo(wsRear,  -carHalfW * 0.88);
513	  ctx.lineTo(wsRear,   carHalfW * 0.88);
514	  ctx.lineTo(wsFront,  carHalfW * 0.84);
515	  ctx.closePath();
516	  ctx.fill();
517	
518	  // Windshield highlight
519	  ctx.fillStyle = 'rgba(180, 210, 255, 0.25)';
520	  ctx.beginPath();
521	  ctx.moveTo(wsFront * 0.85 + wsRear * 0.15, -carHalfW * 0.35);
522	  ctx.lineTo(wsRear * 0.7 + wsFront * 0.3,  -carHalfW * 0.55);
523	  ctx.lineTo(wsRear * 0.7 + wsFront * 0.3,  -carHalfW * 0.15);
524	  ctx.closePath();
525	  ctx.fill();
526	
527	  // ── 4. REAR WINDOW ───────────────────────────────────────────────
528	  const rwFront = -carLen * 0.5 + carLen * cfg.REAR_WINDOW_RATIO;
529	  const rwRear  = -carLen * 0.5 + carLen * 0.05;
530	  ctx.fillStyle = 'rgba(20, 35, 55, 0.6)';
531	  ctx.beginPath();
532	  ctx.moveTo(rwRear,  -carHalfW * 0.82);
533	  ctx.lineTo(rwFront, -carHalfW * 0.85);
534	  ctx.lineTo(rwFront,  carHalfW * 0.85);
535	  ctx.lineTo(rwRear,   carHalfW * 0.82);
536	  ctx.closePath();
537	  ctx.fill();
538	
539	  // ── 5. RACING STRIPE ─────────────────────────────────────────────
540	  const stripeW = cfg.STRIPE_WIDTH * 0.5 * zoom;
541	  ctx.fillStyle = p.accentColor;
542	  ctx.fillRect(-carLen * 0.44, -stripeW, carLen * 0.88, stripeW * 2);
543	
544	  // Thin pinstripe either side of center
545	  ctx.fillStyle = 'rgba(255,255,255,0.2)';
546	  const pinY = stripeW * 2.5;
547	  ctx.fillRect(-carLen * 0.42, -pinY, carLen * 0.84, 0.8 * zoom);
548	  ctx.fillRect(-carLen * 0.42,  pinY, carLen * 0.84, 0.8 * zoom);
549	
550	  // ── 6. HEADLIGHTS ────────────────────────────────────────────────
551	  ctx.fillStyle = '#ffffcc';
552	  ctx.shadowColor = 'rgba(255, 255, 180, 0.6)';
553	  ctx.shadowBlur = 4 * zoom;
554	  ctx.fillRect(bodyFront - 2 * zoom, -carHalfW * 0.72, 5 * zoom, 4 * zoom);
555	  ctx.fillRect(bodyFront - 2 * zoom,  carHalfW * 0.72 - 4 * zoom, 5 * zoom, 4 * zoom);
556	  ctx.shadowColor = 'transparent';
557	  ctx.shadowBlur = 0;
558	
559	  // ── 7. TAILLIGHTS ────────────────────────────────────────────────
560	  // Glow brighter when braking
561	  const brakeGlow = (R.input && R.input.brake) ? 1 : 0.4;
562	  ctx.fillStyle = `rgba(255, 30, 30, ${0.6 + brakeGlow * 0.4})`;
563	  ctx.shadowColor = `rgba(255, 0, 0, ${0.7 * brakeGlow})`;
564	  ctx.shadowBlur = 6 * zoom * brakeGlow;
565	  ctx.fillRect(bodyRear + 0.5 * zoom, -carHalfW * 0.72, 4.5 * zoom, 3.5 * zoom);
566	  ctx.fillRect(bodyRear + 0.5 * zoom,  carHalfW * 0.72 - 3.5 * zoom, 4.5 * zoom, 3.5 * zoom);
567	  ctx.shadowColor = 'transparent';
568	  ctx.shadowBlur = 0;
569	
570	  // ── 8. WHEELS ────────────────────────────────────────────────────
571	  // Steering rotation for front wheels only
572	  const steerVis = p.steerAngle * 0.65; // visual steer reduced for readability
573	
574	  // Wheel positions (local coords)
575	  const wheelPositions = [
576	    { x:  wheelBase * 0.5,  y: -carHalfW - wheelW * 0.2, steer: steerVis, tag: 'FL' },
577	    { x:  wheelBase * 0.5,  y:  carHalfW + wheelW * 0.2, steer: steerVis, tag: 'FR' },
578	    { x: -wheelBase * 0.5,  y: -carHalfW - wheelW * 0.2, steer: 0,        tag: 'RL' },
579	    { x: -wheelBase * 0.5,  y:  carHalfW + wheelW * 0.2, steer: 0,        tag: 'RR' },
580	  ];
581	
582	  for (const wp of wheelPositions) {
583	    ctx.save();
584	    ctx.translate(wp.x, wp.y);
585	    ctx.rotate(wp.steer);
586	
587	    // Tire rubber
588	    ctx.fillStyle = '#1a1a1a';
589	    ctx.fillRect(-wheelLen * 0.5, -wheelW * 0.5, wheelLen, wheelW);
590	
591	    // Tire tread lines
592	    ctx.strokeStyle = '#2a2a2a';
593	    ctx.lineWidth = 0.7 * zoom;
594	    for (let t = -wheelLen * 0.35; t <= wheelLen * 0.35; t += wheelLen * 0.25) {
595	      ctx.beginPath();
596	      ctx.moveTo(t, -wheelW * 0.5);
597	      ctx.lineTo(t,  wheelW * 0.5);
598	      ctx.stroke();
599	    }
600	
601	    // Hub cap (center)
602	    ctx.fillStyle = '#444';
603	    ctx.beginPath();
604	    ctx.arc(0, 0, wheelW * 0.28, 0, Math.PI * 2);
605	    ctx.fill();
606	
607	    // Hub detail (rotating spoke)
608	    const spokeAngle = p.wheelRot * (wp.tag[1] === 'L' ? 1 : -1);
609	    ctx.strokeStyle = '#666';
610	    ctx.lineWidth = 1 * zoom;
611	    ctx.beginPath();
612	    ctx.moveTo(
613	      Math.cos(spokeAngle) * wheelW * 0.2,
614	      Math.sin(spokeAngle) * wheelW * 0.2
615	    );
616	    ctx.lineTo(
617	      Math.cos(spokeAngle + Math.PI) * wheelW * 0.2,
618	      Math.sin(spokeAngle + Math.PI) * wheelW * 0.2
619	    );
620	    ctx.stroke();
621	
622	    ctx.restore();
623	  }
624	
625	  // ── 9. DOOR LINE ─────────────────────────────────────────────────
626	  ctx.strokeStyle = 'rgba(255,255,255,0.08)';
627	  ctx.lineWidth = 1 * zoom;
628	  const doorX = bodyFront - carLen * cfg.DOOR_LINE_OFFSET;
629	  ctx.beginPath();
630	  ctx.moveTo(doorX, -carHalfW * 0.86);
631	  ctx.lineTo(doorX,  carHalfW * 0.86);
632	  ctx.stroke();
633	
634	  // ── 10. EXHAUST FLAME ────────────────────────────────────────────
635	  const throttleOn = R.input && R.input.throttle;
636	  if (throttleOn && p.speed > 0.3) {
637	    const exhX = bodyRear - 2 * zoom;
638	    const exhBaseW = cfg.EXHAUST_BASE_WIDTH * zoom;
639	    const exhLen    = cfg.EXHAUST_LENGTH * zoom;
640	
641	    // Flame flicker
642	    const flicker = 0.7 + Math.random() * 0.3;
643	    const flameLen = exhLen * flicker * (p.boosting ? 1.8 : 1);
644	
645	    // Two exhaust pipes
646	    for (const side of [-1, 1]) {
647	      const exhY = side * carHalfW * 0.5;
648	
649	      // Outer glow
650	      ctx.fillStyle = 'rgba(255, 120, 20, 0.3)';
651	      ctx.beginPath();
652	      ctx.moveTo(exhX, exhY - exhBaseW * 0.5);
653	      ctx.lineTo(exhX - flameLen * 0.4, exhY - exhBaseW * 0.3);
654	      ctx.lineTo(exhX - flameLen, exhY);
655	      ctx.lineTo(exhX - flameLen * 0.4, exhY + exhBaseW * 0.3);
656	      ctx.lineTo(exhX, exhY + exhBaseW * 0.5);
657	      ctx.closePath();
658	      ctx.fill();
659	
660	      // Inner flame (brighter core)
661	      ctx.fillStyle = 'rgba(255, 220, 60, 0.7)';
662	      ctx.beginPath();
663	      ctx.moveTo(exhX, exhY - exhBaseW * 0.22);
664	      ctx.lineTo(exhX - flameLen * 0.55, exhY);
665	      ctx.lineTo(exhX, exhY + exhBaseW * 0.22);
666	      ctx.closePath();
667	      ctx.fill();
668	    }
669	
670	    // Boost glow ring at rear
671	    if (p.boosting) {
672	      ctx.fillStyle = 'rgba(100, 180, 255, 0.4)';
673	      ctx.beginPath();
674	      ctx.arc(bodyRear, 0, carHalfW * 0.9, 0, Math.PI * 2);
675	      ctx.fill();
676	    }
677	  }
678	
679	  ctx.restore();
680	
681	  // ── 11. DRIFT MARKS (world-space, not car-relative) ──────────────
682	  renderDriftMarks();
683	
684	  // ── 12. EXHAUST PARTICLES (world-space) ──────────────────────────
685	  renderExhaustParticles();
686	
687	  // ── 13. BOUNCE MARKERS (world-space) ─────────────────────────────
688	  renderBounceMarkers();
689	};
690	
691	/* ==========================================================================
692	   Drift mark rendering (world-space, called from renderPlayerCar)
693	   ========================================================================== */
694	function renderDriftMarks() {
695	  const ctx = R.ctx;
696	  for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) {
697	    const m = driftMarks[i];
698	    if (!m.alive) continue;
699	    const sc = R.worldToScreen(m.x, m.y);
700	    ctx.fillStyle = `rgba(180, 180, 180, ${m.alpha.toFixed(3)})`;
701	    ctx.beginPath();
702	    ctx.arc(sc.sx, sc.sy, 2.5 * (R.camera ? R.camera.zoom : 1), 0, Math.PI * 2);
703	    ctx.fill();
704	  }
705	}
706	
707	/* ==========================================================================
708	   Exhaust particle rendering
709	   ========================================================================== */
710	function renderExhaustParticles() {
711	  const ctx = R.ctx;
712	  const cam = R.camera || { zoom: 1 };
713	  for (let i = 0; i < EXHAUST_CAPACITY; i++) {
714	    const ep = exhaustParticles[i];
715	    if (!ep.alive) continue;
716	    const sc = R.worldToScreen(ep.x, ep.y);
717	    const lifeRatio = ep.life / ep.maxLife;
718	    const alpha = lifeRatio * 0.7;
719	    const size = ep.size * lifeRatio * cam.zoom;
720	
721	    ctx.fillStyle = `rgba(255, ${Math.floor(140 + lifeRatio * 80)}, 20, ${alpha.toFixed(3)})`;
722	    ctx.beginPath();
723	    ctx.arc(sc.sx, sc.sy, size, 0, Math.PI * 2);
724	    ctx.fill();
725	  }
726	}
727	
728	/* ==========================================================================
729	   Bounce marker rendering
730	   ========================================================================== */
731	function renderBounceMarkers() {
732	  const ctx = R.ctx;
733	  const cam = R.camera || { zoom: 1 };
734	  for (let i = 0; i < BOUNCE_CAPACITY; i++) {
735	    const bm = bounceMarkers[i];
736	    if (!bm.alive) continue;
737	    const sc = R.worldToScreen(bm.x, bm.y);
738	    ctx.strokeStyle = `rgba(255, 255, 255, ${bm.alpha.toFixed(3)})`;
739	    ctx.lineWidth = 2 * cam.zoom;
740	    ctx.beginPath();
741	    ctx.arc(sc.sx, sc.sy, bm.radius * cam.zoom, 0, Math.PI * 2);
742	    ctx.stroke();
743	
744	    // Expanding ring
745	    ctx.strokeStyle = `rgba(255, 200, 80, ${(bm.alpha * 0.5).toFixed(3)})`;
746	    ctx.lineWidth = 1 * cam.zoom;
747	    ctx.beginPath();
748	    ctx.arc(sc.sx, sc.sy, bm.radius * cam.zoom * 1.4, 0, Math.PI * 2);
749	    ctx.stroke();
750	  }
751	}
752	
753	/* ==========================================================================
754	   R.renderPlayerHUD() — Render HUD elements for player state
755	   Speedometer, lap counter, boost gauge.
756	   ========================================================================== */
757	R.renderPlayerHUD = function renderPlayerHUD() {
758	  const p = R.player;
759	  if (!p) return;
760	  const ctx = R.ctx;
761	  const cfg = R.CONFIG;
762	  const W = (R.canvas && R.canvas.width)  || 1280;
763	  const H = (R.canvas && R.canvas.height) || 720;
764	
765	  ctx.save();
766	
767	  // ── Speedometer (bottom-right) ───────────────────────────────────
768	  const speedoX = W - 160;
769	  const speedoY = H - 110;
770	  const speedKmh = Math.round(p.speed * 20); // px/frame → km/h-ish
771	
772	  // Background panel
773	  ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
774	  ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
775	  ctx.lineWidth = 2;
776	  ctx.beginPath();
777	  roundedRect(ctx, speedoX, speedoY, 140, 90, 10);
778	  ctx.fill();
779	  ctx.stroke();
780	
781	  // Speed number
782	  ctx.fillStyle = '#ffffff';
783	  ctx.font = 'bold 36px "Segoe UI", "PingFang SC", sans-serif';
784	  ctx.textAlign = 'right';
785	  ctx.fillText(speedKmh, speedoX + 120, speedoY + 42);
786	
787	  // KM/H label
788	  ctx.fillStyle = 'rgba(255,255,255,0.5)';
789	  ctx.font = '12px "Segoe UI", "PingFang SC", sans-serif';
790	  ctx.fillText('KM/H', speedoX + 120, speedoY + 62);
791	
792	  // Speed bar
793	  const barX = speedoX + 15;
794	  const barW = 110;
795	  const barY = speedoY + 52;
796	  const barH = 5;
797	  const speedPct = p.speed / p.maxSpeed;
798	
799	  ctx.fillStyle = 'rgba(255,255,255,0.12)';
800	  ctx.fillRect(barX, barY, barW, barH);
801	
802	  const barColor = p.boosting ? '#4488ff' : '#00ff88';
803	  ctx.fillStyle = barColor;
804	  ctx.fillRect(barX, barY, barW * speedPct, barH);
805	
806	  // ── Lap Counter (top-right) ──────────────────────────────────────
807	  const lapX = W - 50;
808	  const lapY = 40;
809	
810	  ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
811	  ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
812	  ctx.lineWidth = 2;
813	  ctx.beginPath();
814	  roundedRect(ctx, lapX - 85, lapY - 5, 75, 50, 8);
815	  ctx.fill();
816	  ctx.stroke();
817	
818	  ctx.fillStyle = 'rgba(255,255,255,0.5)';
819	  ctx.font = '11px "Segoe UI", "PingFang SC", sans-serif';
820	  ctx.textAlign = 'right';
821	  ctx.fillText('LAP', lapX, lapY + 14);
822	
823	  ctx.fillStyle = '#ffffff';
824	  ctx.font = 'bold 24px "Segoe UI", "PingFang SC", sans-serif';
825	  const lapDisplay = Math.min(p.lap + 1, cfg.TOTAL_LAPS);
826	  ctx.fillText(lapDisplay + '/' + cfg.TOTAL_LAPS, lapX, lapY + 40);
827	
828	  // ── Boost Gauge (bottom-right, above speedo) ─────────────────────
829	  const boostX = W - 160;
830	  const boostY = speedoY - 45;
831	  const boostReady = p.boostCooldown <= 0 && !p.boosting;
832	
833	  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
834	  ctx.strokeStyle = boostReady ? 'rgba(100, 180, 255, 0.7)' : 'rgba(255,255,255,0.12)';
835	  ctx.lineWidth = boostReady ? 2 : 1;
836	  ctx.beginPath();
837	  roundedRect(ctx, boostX, boostY, 140, 28, 6);
838	  ctx.fill();
839	  ctx.stroke();
840	
841	  if (p.boosting) {
842	    // Active boost — pulsing bar
843	    const pulse = 0.6 + Math.sin(R.state.time * 20) * 0.4;
844	    const boostPct = p.boostTimer / R.CONFIG.BOOST_DURATION;
845	    ctx.fillStyle = `rgba(68, 136, 255, ${pulse.toFixed(2)})`;
846	    ctx.fillRect(boostX + 3, boostY + 3, 134 * boostPct, 22);
847	    ctx.fillStyle = '#ffffff';
848	    ctx.font = 'bold 13px "Segoe UI", "PingFang SC", sans-serif';
849	    ctx.textAlign = 'center';
850	    ctx.fillText('BOOST!', boostX + 70, boostY + 19);
851	  } else if (!boostReady) {
852	    // Cooldown
853	    const cdPct = 1 - (p.boostCooldown / (R.CONFIG.BOOST_COOLDOWN + R.CONFIG.BOOST_DURATION));
854	    ctx.fillStyle = 'rgba(100, 100, 120, 0.6)';
855	    ctx.fillRect(boostX + 3, boostY + 3, 134 * cdPct, 22);
856	    ctx.fillStyle = 'rgba(255,255,255,0.5)';
857	    ctx.font = '11px "Segoe UI", "PingFang SC", sans-serif';
858	    ctx.textAlign = 'center';
859	    ctx.fillText(Math.ceil(p.boostCooldown) + 's', boostX + 70, boostY + 18);
860	  } else {
861	    ctx.fillStyle = 'rgba(255,255,255,0.45)';
862	    ctx.font = '12px "Segoe UI", "PingFang SC", sans-serif';
863	    ctx.textAlign = 'center';
864	    ctx.fillText('BOOST READY', boostX + 70, boostY + 18);
865	  }
866	
867	  // ── Drift indicator ──────────────────────────────────────────────
868	  if (p.isDrifting) {
869	    const driftX = W / 2;
870	    const driftY = H - 60;
871	    ctx.fillStyle = 'rgba(255, 150, 30, 0.8)';
872	    ctx.font = 'bold italic 16px "Segoe UI", "PingFang SC", sans-serif';
873	    ctx.textAlign = 'center';
874	    ctx.fillText('DRIFT', driftX, driftY);
875	  }
876	
877	  ctx.restore();
878	};
