880	/* ==========================================================================
881	   R.getPlayerWorldZ()
882	   Returns player.z (distance along track). Used by other systems.
883	   ========================================================================== */
884	R.getPlayerWorldZ = function getPlayerWorldZ() {
885	  return R.player ? R.player.z : 0;
886	};
887	
888	/* ==========================================================================
889	   R.getPlayerSpeed()
890	   Convenience accessor for AI / HUD / other systems.
891	   ========================================================================== */
892	R.getPlayerSpeed = function getPlayerSpeed() {
893	  return R.player ? R.player.speed : 0;
894	};
895	
896	/* ==========================================================================
897	   R.getPlayerPosition()
898	   Returns { x, y, z, angle } — used by camera and AI systems.
899	   ========================================================================== */
900	R.getPlayerPosition = function getPlayerPosition() {
901	  const p = R.player;
902	  if (!p) return { x: 0, y: 0, z: 0, angle: 0 };
903	  return { x: p.x, y: p.y, z: p.z, angle: p.angle };
904	};
905	
906	/* ==========================================================================
907	   R.resetPlayerForRetry()
908	   Reset player state for restart without full re-initialization.
909	   ========================================================================== */
910	R.resetPlayerForRetry = function resetPlayerForRetry() {
911	  const p = R.player;
912	  if (!p) { R.initPlayer(); return; }
913	
914	  const seg0 = (R.track && R.track.segments && R.track.segments.length)
915	    ? R.track.segments[0]
916	    : { worldX: 0, worldY: 0, worldZ: 0 };
917	
918	  p.x             = seg0.worldX || 0;
919	  p.y             = seg0.worldY || 0;
920	  p.z             = 0;
921	  p.angle         = 0;
922	  p.speed         = 0;
923	  p.steerAngle    = 0;
924	  p.driftFactor   = 0;
925	  p.isDrifting    = false;
926	  p.boosting      = false;
927	  p.boostTimer    = 0;
928	  p.boostCooldown = 0;
929	  p.lap           = 0;
930	  p.checkpointIdx = 0;
931	  p.finished      = false;
932	  p.wheelRot      = 0;
933	
934	  // Clear visual pools
935	  for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) driftMarks[i].alive = false;
936	  for (let i = 0; i < EXHAUST_CAPACITY;  i++) exhaustParticles[i].alive = false;
937	  for (let i = 0; i < BOUNCE_CAPACITY;   i++) bounceMarkers[i].alive = false;
938	};
939	
940	/* ==========================================================================
941	   R.isPlayerFinished()
942	   Returns true if the player has completed all laps.
943	   ========================================================================== */
944	R.isPlayerFinished = function isPlayerFinished() {
945	  return R.player ? R.player.finished : false;
946	};
947	
948	/* ==========================================================================
949	   UTILITY: roundedRect helper
950	   ========================================================================== */
951	
952	/**
953	 * Draw a rounded rectangle path on the current context.
954	 * @param {CanvasRenderingContext2D} ctx
955	 * @param {number} x - left
956	 * @param {number} y - top
957	 * @param {number} w - width
958	 * @param {number} h - height
959	 * @param {number} r - corner radius
960	 */
961	function roundedRect(ctx, x, y, w, h, r) {
962	  r = Math.min(r, w / 2, h / 2);
963	  ctx.moveTo(x + r, y);
964	  ctx.lineTo(x + w - r, y);
965	  ctx.arcTo(x + w, y, x + w, y + r, r);
966	  ctx.lineTo(x + w, y + h - r);
967	  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
968	  ctx.lineTo(x + r, y + h);
969	  ctx.arcTo(x, y + h, x, y + h - r, r);
970	  ctx.lineTo(x, y + r);
971	  ctx.arcTo(x, y, x + r, y, r);
972	  ctx.closePath();
973	}
974	
975	/* ==========================================================================
976	   EXPORTS
977	   ==========================================================================
978	   Attached to window.R:
979	     R.initPlayer()
980	     R.updatePlayer(dt)
981	     R.renderPlayerCar()
982	     R.renderPlayerHUD()
983	     R.getPlayerWorldZ()
984	     R.getPlayerSpeed()
985	     R.getPlayerPosition()
986	     R.playerCollide(ox, oy, oRadius)
987	     R.resetPlayerForRetry()
988	     R.isPlayerFinished()
989	     R.player            — car state object
990	   Internal:
991	     roundedRect(ctx, x, y, w, h, r)
992	     R.worldToScreen(wx, wy)
993	     driftMarks[]        — circular buffer
994	     exhaustParticles[]  — circular buffer
995	     bounceMarkers[]     — circular buffer
996	   ========================================================================== */
997

