1	/**
2	 * Rail Runner — Core Logic Unit Tests
3	 *
4	 * Tests pure functions extracted from src/index.html.
5	 * No DOM/Canvas dependency — all functions are deterministic.
6	 *
7	 * Run: npx vitest run tests/unit/core-logic.test.js
8	 *   or: node --test tests/unit/core-logic.test.js  (Node 18+ native test runner)
9	 */
10	
11	// ====================================================================
12	// Pure functions extracted from game code (copy of src/index.html logic)
13	// ====================================================================
14	
15	function lerp(a, b, t) {
16	  return a + (b - a) * t;
17	}
18	
19	function clamp(v, lo, hi) {
20	  return v < lo ? lo : v > hi ? hi : v;
21	}
22	
23	// Constants from game code
24	const LANE_COUNT = 3;
25	const PLAYER_LANE = 1;
26	const MAX_HEARTS = 3;
27	const INVINCIBLE_FRAMES = 90;
28	const BASE_SPEED = 3.5;
29	const MAX_SPEED = 14;
30	const SPEED_INC = 0.0004;
31	const DISTANCE_PER_FRAME = 0.6;
32	const COIN_SCORE = 50;
33	const DISTANCE_SCORE = 1;
34	
35	const OBS_LOW = 'low';
36	const OBS_MID = 'mid';
37	const OBS_HIGH = 'high';
38	
39	const STATE_RUN = 'run';
40	const STATE_JUMP = 'jump';
41	const STATE_SLIDE = 'slide';
42	const STATE_HIT = 'hit';
43	
44	// World-to-screen projection (needs G-like config)
45	function makeWorldToScreen(W, H) {
46	  const vanishX = W * 0.5;
47	  const vanishY = H * 0.28;
48	  const groundY = H * 0.88;
49	  const maxDist = 800;
50	  return function worldToScreen(dist) {
51	    const t = 1 - clamp(dist / maxDist, 0, 1);
52	    const y = lerp(vanishY, groundY, t);
53	    const scale = lerp(0.15, 1.0, t);
54	    return { y, scale };
55	  };
56	}
57	
58	function makeLaneX(W) {
59	  const vanishX = W * 0.5;
60	  const laneSpread = W * 0.18;
61	  const maxDist = 800;
62	  return function laneX(laneIdx, dist) {
63	    const t = 1 - clamp(dist / maxDist, 0, 1);
64	    const spread = lerp(0, laneSpread, t);
65	    return vanishX + (laneIdx - 1) * spread;
66	  };
67	}
68	
69	function sameLane(obsLane, playerLane) {
70	  return Math.abs(obsLane - playerLane) < 0.6;
71	}
72	
73	function calcScore(distance, coinsCollected) {
74	  return Math.floor(distance * DISTANCE_SCORE) + coinsCollected * COIN_SCORE;
75	}
76	
77	function calcSpeed(framesElapsed) {
78	  return Math.min(BASE_SPEED + SPEED_INC * framesElapsed, MAX_SPEED);
79	}
80	
81	function calcDistance(speed, framesElapsed) {
82	  return speed * DISTANCE_PER_FRAME * framesElapsed;
83	}
84	
85	function selectObstacleTypes(speed) {
86	  const speedRatio = (speed - BASE_SPEED) / (MAX_SPEED - BASE_SPEED);
87	  if (speedRatio < 0.2) {
88	    return [OBS_LOW, OBS_LOW, OBS_MID];
89	  } else if (speedRatio < 0.5) {
90	    return [OBS_LOW, OBS_MID, OBS_MID, OBS_HIGH];
91	  } else {
92	    return [OBS_LOW, OBS_MID, OBS_HIGH, OBS_HIGH];
93	  }
94	}
95	
96	function canPassObstacle(obsType, playerState) {
97	  if (obsType === OBS_LOW && playerState === STATE_SLIDE) return true;
98	  if (obsType === OBS_MID && playerState === STATE_JUMP) return true;
99	  if (obsType === OBS_HIGH) return false; // must switch lane
100	  return false; // wrong state for this obstacle
101	}
102	
103	// Pool operations
104	function poolGet(pool, factory) {
105	  for (let i = 0; i < pool.length; i++) {
106	    if (!pool[i].active) {
107	      pool[i].active = true;
108	      return pool[i];
109	    }
110	  }
111	  const obj = factory();
112	  obj.active = true;
113	  pool.push(obj);
114	  return obj;
115	}
116	
117	function poolReleaseAll(pool) {
118	  for (let i = 0; i < pool.length; i++) pool[i].active = false;
119	}
120	
121	function createPlayer() {
122	  return {
123	    lane: PLAYER_LANE,
124	    targetLane: PLAYER_LANE,
125	    state: STATE_RUN,
126	    stateTimer: 0,
127	    jumpVel: 0,
128	    slideTimer: 0,
129	    animFrame: 0,
130	    animTimer: 0,
131	    x: 0, y: 0,
132	    scale: 1,
133	  };
134	}
135	
136	function createObstacle(lane, type, dist) {
137	  return {
138	    active: true,
139	    lane,
140	    type,
141	    dist,
142	    passed: false,
143	  };
144	}
145	
146	function createCoin(lane, dist) {
147	  return {
148	    active: true,
149	    lane,
150	    dist,
151	    collected: false,
152	    sparkTimer: 0,
153	  };
154	}
155	
156	function hurtPlayer(hearts, invincible, damage) {
157	  if (invincible > 0) return { hearts, invincible, died: false, hit: false };
158	  const newHearts = hearts - damage;
159	  const newInvincible = INVINCIBLE_FRAMES;
160	  if (newHearts <= 0) {
161	    return { hearts: 0, invincible: newInvincible, died: true, hit: true };
162	  }
163	  return { hearts: newHearts, invincible: newInvincible, died: false, hit: true };
164	}
165	
166	function clampLane(lane) {
167	  return clamp(lane, 0, LANE_COUNT - 1);
168	}
169	
170	// ====================================================================
171	// Tests
172	// ====================================================================
173	
174	// --- lerp ---
175	function test_lerp() {
176	  console.assert(lerp(0, 10, 0.5) === 5, 'lerp midpoint');
177	  console.assert(lerp(0, 10, 0) === 0, 'lerp start');
178	  console.assert(lerp(0, 10, 1) === 10, 'lerp end');
179	  console.assert(lerp(-5, 5, 0.5) === 0, 'lerp negative range');
180	}
181	
182	// --- clamp ---
183	function test_clamp() {
184	  console.assert(clamp(5, 0, 10) === 5, 'clamp within');
185	  console.assert(clamp(-3, 0, 10) === 0, 'clamp below');
186	  console.assert(clamp(15, 0, 10) === 10, 'clamp above');
187	  console.assert(clamp(0, 0, 10) === 0, 'clamp at boundary');
188	}
189	
190	// --- worldToScreen ---
191	function test_worldToScreen() {
192	  const w2s = makeWorldToScreen(400, 800);
193	
194	  // At distance 0 (player position) -> should be at groundY
195	  const near = w2s(0);
196	  console.assert(near.y === 800 * 0.88, `worldToScreen(0) y=${near.y} expected ${800*0.88}`);
197	  console.assert(near.scale === 1.0, 'worldToScreen(0) scale=1.0');
198	
199	  // At maxDistance -> should be at vanishY, scale 0.15
200	  const far = w2s(800);
201	  console.assert(far.y === 800 * 0.28, `worldToScreen(800) y=${far.y} expected ${800*0.28}`);
202	  console.assert(far.scale === 0.15, `worldToScreen(800) scale=${far.scale} expected 0.15`);
203	
204	  // Monotonic: farther = higher on screen (smaller y)
205	  const mid = w2s(400);
206	  console.assert(mid.y > far.y && mid.y < near.y, 'worldToScreen monotonic');
207	  console.assert(mid.scale < near.scale && mid.scale > far.scale, 'worldToScreen scale monotonic');
208	}
209	
210	// --- laneX ---
211	function test_laneX() {
212	  const lx = makeLaneX(400);
213	
214	  // At distance 0, lanes are spread by laneSpread
215	  const leftNear = lx(0, 0);
216	  const centerNear = lx(1, 0);
217	  const rightNear = lx(2, 0);
218	  console.assert(centerNear === 200, `laneX(1,0)=${centerNear} expected 200`);
219	  console.assert(leftNear < centerNear && centerNear < rightNear, 'laneX order at dist=0');
220	
221	  // At maxDistance, all lanes converge to vanishX
222	  const leftFar = lx(0, 800);
223	  const rightFar = lx(2, 800);
224	  console.assert(Math.abs(leftFar - 200) < 0.01, `laneX(0,800)=${leftFar} expected ~200`);
225	  console.assert(Math.abs(rightFar - 200) < 0.01, `laneX(2,800)=${rightFar} expected ~200`);
226	}
227	
228	// --- sameLane ---
229	function test_sameLane() {
230	  console.assert(sameLane(1, 1.0) === true, 'sameLane exact match');
231	  console.assert(sameLane(1, 1.5) === true, 'sameLane within tolerance');
232	  console.assert(sameLane(1, 1.7) === false, 'sameLane outside tolerance');
233	  console.assert(sameLane(0, 2) === false, 'sameLane far apart');
