// ============================================================================
// Player config overrides — verify ensurePlayerConfig behavior
//
// BUG DOCUMENTED: ensurePlayerConfig uses `if (!(k in R.CONFIG))` which
// only fills MISSING keys. Since config.js loads first and sets all these
// keys, player.js's tuned values (seconds, 0.08 accel, 0.985 friction)
// are NEVER applied. The session state claims these were "fixed" but
// the fix is dead code.
// ============================================================================
describe('Player config: ensurePlayerConfig merge behavior', () => {
  it('does NOT override BOOST_DURATION (config.js wins)', () => {
    // config.js sets 90 (frames). player.js defaults to 1.5 (seconds) but
    // the `in` check prevents override because config.js already set this key.
    expect(R.CONFIG.BOOST_DURATION).toBe(90);
  });

  it('does NOT override BOOST_COOLDOWN (config.js wins)', () => {
    expect(R.CONFIG.BOOST_COOLDOWN).toBe(300);
  });

  it('does NOT override ACCELERATION (config.js wins)', () => {
    expect(R.CONFIG.ACCELERATION).toBe(0.15);
  });

  it('does NOT override FRICTION (config.js wins)', () => {
    expect(R.CONFIG.FRICTION).toBe(0.96);
  });

  it.todo('FIX: should override BOOST_DURATION to 1.5 seconds', () => {
    // ensurePlayerConfig should OVERWRITE, not just fill missing keys.
    // Change pattern from if(!(k in R.CONFIG)) to direct assignment
    // for keys that MUST be overridden.
    expect(R.CONFIG.BOOST_DURATION).toBe(1.5);
  });
});

